package checks;
import net.minecraft.client.Minecraft;import com.raiiiden.warborn.hybrid.HybridClient6;import net.neoforged.neoforge.client.event.RenderLevelStageEvent;import net.minecraft.server.level.ServerPlayer;import com.raiiiden.warborn.common.item.*;import com.raiiiden.warborn.common.util.*;import com.raiiiden.warborn.client.util.NvgClient2;import com.raiiiden.warborn.client.shader.*;import com.raiiiden.warborn.client.network.ClientBatteryUpdateHandler;
public class HybridModeChecks{static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("hybrid mode "+n);}public static void main(String[]a){Minecraft mc=Minecraft.getInstance();ServerPlayer p=new ServerPlayer();mc.player=p;mc.level=p.world;p.helmet=NvgChecks.helmet(new WBArmorItem(),"thermal_hybrid",50000);NvgClient2.tick(null);ok(NvgChecks.active(p).isEmpty());ok(NvgLink2.mode(p.helmet).equals("thermal_hybrid"));NvgChecks.lowered(p);NvgClient2.tick(null);ok(NvgChecks.active(p).equals("thermal_hybrid"));ok(ShaderRegistry.INSTANCE.enabled.get("htvg"));ok(!ShaderRegistry.INSTANCE.isShaderActive("htvg"));HybridClient6.beginFrame();ok(!HybridClient6.active());HybridClient6.stage(new RenderLevelStageEvent(RenderLevelStageEvent.Stage.AFTER_SKY));ok(HybridClient6.active());HybridClient6.stage(new RenderLevelStageEvent(RenderLevelStageEvent.Stage.AFTER_LEVEL));ok(!HybridClient6.active());HybridClient6.stage(new RenderLevelStageEvent(RenderLevelStageEvent.Stage.AFTER_SKY));ok(HybridClient6.active());HybridClient6.beginFrame();ok(!HybridClient6.active());ok(NvgLink2.authorize("thermal_hybrid",p).equals("thermal_hybrid"));ok(NvgClient2.ownsPostEffect());((WBArmorItem)p.helmet.item).setTopOpen(p.helmet,true);NvgClient2.tick(null);ok(NvgChecks.active(p).isEmpty()&&!ShaderRegistry.INSTANCE.enabled.get("htvg"));NvgChecks.lowered(p);NvgClient2.tick(null);ClientBatteryUpdateHandler.handle(0);NvgClient2.empty();ok(NvgChecks.active(p).isEmpty()&&!ShaderRegistry.INSTANCE.enabled.get("htvg"));System.out.println("HYBRID_MANUAL_ACTIVATION_BATTERY_CHECKS="+n);}}
